for root in EXTRA:
    for dp,ds,fs in os.walk(root):
        if '10_' in dp or '_cand' in dp or '/fr' in dp or '/hero' in dp: continue
        for f in fs:
            if f.lower().endswith(('.jpg','.jpeg','.png','.heic')) and not f.startswith(('._','_rev','sheet')): paths.setdefault(f,os.path.join(dp,f))
